import React from 'react';

function RequestCard({ req, user, onAccept, onNotify }) {
  return (
    <div className="bg-white rounded-xl shadow-md p-6 border border-gray-100 hover:shadow-lg transition-shadow duration-200">
      <div className="mb-2 text-gray-700">
        <span className="font-semibold">Book:</span> {req.book?.title || 'N/A'}
      </div>
      <div className="mb-2 text-gray-700">
        <span className="font-semibold">Student:</span> {req.student?.name || 'N/A'}
      </div>
      <div className="mb-4 text-gray-700">
        <span className="font-semibold">Status:</span> 
        <span className={`ml-2 px-2 py-1 rounded-full text-xs font-medium ${
          req.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
          req.status === 'accepted' ? 'bg-green-100 text-green-800' :
          'bg-gray-100 text-gray-800'
        }`}>
          {req.status}
        </span>
      </div>
      {user?.role === 'librarian' && req.status === 'pending' && (
        <button 
          className="px-4 py-2 bg-green-600 text-white border-none rounded-lg font-semibold cursor-pointer hover:bg-green-700 transition-colors duration-200"
          onClick={() => onAccept(req._id)}
        >
          Accept
        </button>
      )}
      {user?.role === 'librarian' && req.status === 'accepted' && (
        <button 
          className="px-4 py-2 bg-blue-600 text-white border-none rounded-lg font-semibold cursor-pointer hover:bg-blue-700 transition-colors duration-200"
          onClick={() => onNotify(req._id)}
        >
          Send Reminder
        </button>
      )}
    </div>
  );
}

export default RequestCard;
